  TRY_CAST(lower(`is_remote_worker`) IN ('true','1','yes') AS BOOLEAN) AS `is_remote_worker`,
  nullif(`language_preference`, '') AS `language_preference`,
  TRY_CAST(nullif(`last_performance_review_date`,'') AS DATE) AS `last_performance_review_date`,
  TRY_CAST(nullif(`next_performance_review_due`,'') AS DATE) AS `next_performance_review_due`,
  nullif(`phone_number`, '') AS `phone_number`,
  nullif(`primary_contact_method`, '') AS `primary_contact_method`,
  TRY_CAST(`quota_annual_cases` AS DECIMAL(18,2)) AS `quota_annual_cases`,
  TRY_CAST(`quota_annual_revenue` AS DECIMAL(18,2)) AS `quota_annual_revenue`,
  nullif(`record_source`, '') AS `record_source`,
  nullif(`rep_type`, '') AS `rep_type`,
  nullif(`sales_channel`, '') AS `sales_channel`,
  nullif(`sales_district`, '') AS `sales_district`,
  nullif(`sales_force_user_code`, '') AS `sales_force_user_code`,
  nullif(`sales_region`, '') AS `sales_region`,
  nullif(`sap_employee_number`, '') AS `sap_employee_number`,
  TRY_CAST(nullif(`termination_date`,'') AS DATE) AS `termination_date`,
  nullif(`territory_code`, '') AS `territory_code`,
