-- silver: sales_core.territory  （型変換 + PK/FK + expectations）
CREATE OR REFRESH MATERIALIZED VIEW `rongzi_catalog_dev`.`sales_core`.`territory` (
  `territory_id` BIGINT NOT NULL COMMENT 'System-generated unique identifier for the sales territory.',
