  TRY_CAST(nullif(`effective_end_date`,'') AS DATE) AS `effective_end_date`,
  TRY_CAST(nullif(`effective_start_date`,'') AS DATE) AS `effective_start_date`,
  TRY_CAST(lower(`is_exclusive`) IN ('true','1','yes') AS BOOLEAN) AS `is_exclusive`,
  TRY_CAST(nullif(`last_review_date`,'') AS DATE) AS `last_review_date`,
  TRY_CAST(`market_share_target_percent` AS DECIMAL(18,2)) AS `market_share_target_percent`,
  nullif(`priority_level`, '') AS `priority_level`,
  TRY_CAST(`quota_amount` AS DECIMAL(18,2)) AS `quota_amount`,
  nullif(`region`, '') AS `region`,
  TRY_CAST(`sales_target_amount` AS DECIMAL(18,2)) AS `sales_target_amount`,
  nullif(`state_province_list`, '') AS `state_province_list`,
  nullif(`tdp_coverage_target`, '') AS `tdp_coverage_target`,
  nullif(`territory_code`, '') AS `territory_code`,
  nullif(`territory_description`, '') AS `territory_description`,
  nullif(`territory_name`, '') AS `territory_name`,
  nullif(`territory_status`, '') AS `territory_status`,
  nullif(`territory_type`, '') AS `territory_type`,
  TRY_CAST(nullif(`updated_timestamp`,'') AS TIMESTAMP) AS `updated_timestamp`
FROM `rongzi_catalog_dev`.`ops_landing`.`salesforce__territory_raw`;

