  `currency_code` STRING COMMENT 'Three‑letter ISO currency code for the monetary values.. Valid values are `JPY`',
  `data_source` STRING COMMENT 'Origin of the POS record (retailer feed, syndicated provider, or direct partnership).. Valid values are `Nielsen panel (projected, ~15% ACV)`',
  `display_flag` BOOLEAN COMMENT 'True if the product was featured on a shelf display at time of sale.',
  `dollar_sales` DECIMAL(18,2) COMMENT 'Total sales amount in dollars for the line (units × price).',
  `feature_flag` BOOLEAN COMMENT 'True if the product was part of a special feature (e.g., end‑cap).',
  `line_number` STRING COMMENT 'Sequential number of the line within the receipt.',
  `month_of_year` STRING COMMENT 'Month number (1‑12) for the transaction date.',
  `pos_terminal_code` STRING COMMENT 'Identifier of the point‑of‑sale terminal that captured the scan.',
  `price_type` STRING COMMENT 'Classification of the price applied (regular, promotional, discount).. Valid values are `regular|promo|discount`',
  `product_category` STRING COMMENT 'High‑level category of the product (e.g., Beverage, Snack).',
  `product_subcategory` STRING COMMENT 'More specific subcategory within the product category.',
  `promotion_flag` BOOLEAN COMMENT 'Indicates whether the unit was sold under a promotional price.',
  `receipt_number` BIGINT COMMENT 'Identifier linking this line to the parent receipt or transaction header.',
  `record_audit_created` TIMESTAMP COMMENT 'Timestamp when the record was first ingested into the lakehouse.',
  `record_audit_updated` TIMESTAMP COMMENT 'Timestamp of the most recent update to the record.',
  `retailer_banner` STRING COMMENT 'Name of the retailer banner or chain (e.g., Walmart, Kroger).',
  `sales_channel` STRING COMMENT 'Channel through which the sale was made.. Valid values are `CVS|DgS|EC|SM|卸`',
  `scan_timestamp` TIMESTAMP COMMENT 'Timestamp when the barcode was scanned by the terminal.',
  `store_format` STRING COMMENT 'Classification of the store format.. Valid values are `CVS|DgS|EC|SM|卸`',
  `store_region` STRING COMMENT 'Geographic region where the store is located (e.g., Northeast, Midwest).',
  `transaction_date` DATE COMMENT 'Calendar date of the transaction (store local time).',
  `transaction_day_of_week` STRING COMMENT 'Day of week on which the transaction occurred. [ENUM-REF-CANDIDATE: Mon|Tue|Wed|Thu|Fri|Sat|Sun — 7 candidates stripped; promote to reference product]',
  `transaction_reference_number` STRING COMMENT 'Business‑level identifier for the transaction (may be receipt number).',
  `transaction_status` STRING COMMENT 'Current processing status of the transaction line.. Valid values are `settled`',
  `transaction_timestamp` TIMESTAMP COMMENT 'Exact timestamp when the transaction was recorded.',
  `transaction_type` STRING COMMENT 'Nature of the transaction line (sale, return, or inventory adjustment).. Valid values are `sale|return|adjustment`',
  `transaction_week` STRING COMMENT 'Week number (1‑52) derived from transaction_date.',
  `units_sold` STRING COMMENT 'Number of units of the product scanned in this line.',
  `week_of_year` STRING COMMENT 'ISO week number for the transaction date.',
  `year` STRING COMMENT 'Four‑digit year of the transaction.',
  CONSTRAINT ex_units_positive EXPECT (units_sold > 0) ON VIOLATION DROP ROW,
  CONSTRAINT ex_sales_non_negative EXPECT (dollar_sales >= 0) ON VIOLATION DROP ROW,
  CONSTRAINT ex_panel_source_known EXPECT (data_source IS NOT NULL),
  CONSTRAINT pk_pos_transaction PRIMARY KEY(`pos_transaction_id`),
  CONSTRAINT fk_sales_pos_transaction_account_id FOREIGN KEY (`account_id`) REFERENCES `rongzi_catalog_dev`.`sales_core`.`account`(`account_id`) NOT ENFORCED,
  CONSTRAINT fk_sales_pos_transaction_sku_id FOREIGN KEY (`sku_id`) REFERENCES `rongzi_catalog_dev`.`master_core`.`sku`(`sku_id`) NOT ENFORCED
)
COMMENT '【データの出所】Nielsen の syndicated パネル。全店 census ではなく約15% ACV の投影値。 Point-of-sale scan data record capturing consumer purchase activity at the retail store level, sourced from retailer POS feeds, syndicated data providers (Nielsen/IRI/Circana/SPINS), and direct retailer data sharing programs (e.g., Walmart Luminate, Kroger 84.51°). Captures store ID, retailer banner, UPC/GTIN, transaction date/week, units sold, dollar sales, average retail price, promoted/display/feature flags, and data source. SSOT for raw/ingested POS scan data within the enterprise; analytics and insights domains consume this data for derived metrics (market share, promotional lift, price elasticity) but do not own the source records. Enables sell-through velocity analysis, promotional lift measurement, share tracking, and category management insights at the store-week-SKU grain.'
AS SELECT
  TRY_CAST(`pos_transaction_id` AS BIGINT) AS `pos_transaction_id`,
  TRY_CAST(`account_id` AS BIGINT) AS `account_id`,
  TRY_CAST(`sku_id` AS BIGINT) AS `sku_id`,
  TRY_CAST(`stock_position_id` AS BIGINT) AS `stock_position_id`,
  TRY_CAST(`average_price` AS DECIMAL(18,2)) AS `average_price`,
  nullif(`currency_code`, '') AS `currency_code`,
  nullif(`data_source`, '') AS `data_source`,
  TRY_CAST(lower(`display_flag`) IN ('true','1','yes') AS BOOLEAN) AS `display_flag`,
  TRY_CAST(`dollar_sales` AS DECIMAL(18,2)) AS `dollar_sales`,
  TRY_CAST(lower(`feature_flag`) IN ('true','1','yes') AS BOOLEAN) AS `feature_flag`,
  nullif(`line_number`, '') AS `line_number`,
  nullif(`month_of_year`, '') AS `month_of_year`,
  nullif(`pos_terminal_code`, '') AS `pos_terminal_code`,
  nullif(`price_type`, '') AS `price_type`,
  nullif(`product_category`, '') AS `product_category`,
  nullif(`product_subcategory`, '') AS `product_subcategory`,
  TRY_CAST(lower(`promotion_flag`) IN ('true','1','yes') AS BOOLEAN) AS `promotion_flag`,
  TRY_CAST(`receipt_number` AS BIGINT) AS `receipt_number`,
  TRY_CAST(nullif(`record_audit_created`,'') AS TIMESTAMP) AS `record_audit_created`,
  TRY_CAST(nullif(`record_audit_updated`,'') AS TIMESTAMP) AS `record_audit_updated`,
  nullif(`retailer_banner`, '') AS `retailer_banner`,
  nullif(`sales_channel`, '') AS `sales_channel`,
  TRY_CAST(nullif(`scan_timestamp`,'') AS TIMESTAMP) AS `scan_timestamp`,
  nullif(`store_format`, '') AS `store_format`,
  nullif(`store_region`, '') AS `store_region`,
  TRY_CAST(nullif(`transaction_date`,'') AS DATE) AS `transaction_date`,
  nullif(`transaction_day_of_week`, '') AS `transaction_day_of_week`,
  nullif(`transaction_reference_number`, '') AS `transaction_reference_number`,
  nullif(`transaction_status`, '') AS `transaction_status`,
  TRY_CAST(nullif(`transaction_timestamp`,'') AS TIMESTAMP) AS `transaction_timestamp`,
  nullif(`transaction_type`, '') AS `transaction_type`,
  nullif(`transaction_week`, '') AS `transaction_week`,
  nullif(`units_sold`, '') AS `units_sold`,
  nullif(`week_of_year`, '') AS `week_of_year`,
  nullif(`year`, '') AS `year`
FROM `rongzi_catalog_dev`.`ops_landing`.`pos_edi852__pos_transaction_raw`;

-- silver: sales_core.distribution_point  （型変換 + PK/FK + expectations）
CREATE OR REFRESH MATERIALIZED VIEW `rongzi_catalog_dev`.`sales_core`.`distribution_point` (
  `distribution_point_id` BIGINT NOT NULL COMMENT 'Unique system-generated identifier for the distribution point record.',
  `account_id` BIGINT COMMENT 'Foreign key linking to customer.account. Business justification: Needed for Distribution Planning Dashboard, associating each distribution point with the retailer account it serves to allocate inventory.',
  `brand_id` BIGINT COMMENT 'Foreign key linking to marketing.brand. Business justification: Distribution points capture presence of each brand; linking allows brand distribution metrics and market coverage reporting.',
  `center_id` BIGINT COMMENT 'Foreign key linking to distribution.distribution_center. Business justification: Supports Distribution Point Allocation report linking retailer points to the supplying distribution center for inventory planning.',
  `product_registration_id` BIGINT COMMENT 'Foreign key linking to regulatory.product_registration. Business justification: Distribution planning uses product registration data to ensure only compliant products are stocked at each point.',
  `sku_id` BIGINT COMMENT 'Foreign key linking to product.sku. Business justification: Distribution analytics require linking each distribution point record to the exact SKU to track inventory, velocity, and shelf‑life per product.',
  `acv_change_pct` DECIMAL(18,2) COMMENT 'Percent change in ACV weighted distribution versus prior period.',
  `acv_weighted_distribution_pct` DECIMAL(18,2) COMMENT 'Percentage of ACV represented by outlets where the SKU is active, weighted by sales volume.',
  `classification_type` STRING COMMENT 'Category of outlet: retail store, foodservice location, or direct‑to‑consumer channel.. Valid values are `must_stock|optional|seasonal`',
  `created_timestamp` TIMESTAMP COMMENT 'Timestamp when the distribution point record was first created in the system.',
  `data_source` STRING COMMENT 'Origin of the syndicated data snapshot (Nielsen, IRI, or Circana).. Valid values are `Nielsen`',
  `distribution_point_code` STRING COMMENT 'Business‑assigned code uniquely identifying the distribution point within the organization.',
  `distribution_status` STRING COMMENT 'Current status of the SKU at the outlet: authorized (contracted), active (selling), or voided (no longer carried).. Valid values are `authorized|pending|void`',
  `in_stock_flag` BOOLEAN COMMENT 'True if the SKU is currently stocked at the outlet; false otherwise.',
  `location_name` STRING COMMENT 'Human‑readable name of the outlet or distribution point.',
  `market_area` STRING COMMENT 'Geographic market region or sales territory for the outlet.',
  `numeric_distribution_change_pct` DECIMAL(18,2) COMMENT 'Percent change in numeric distribution versus prior period.',
  `numeric_distribution_pct` DECIMAL(18,2) COMMENT 'Percentage of total outlets carrying the SKU, regardless of sales weight.',
  `period_over_period_change_pct` DECIMAL(18,2) COMMENT 'Percent change of the primary metric compared to the previous period.',
  `period_type` STRING COMMENT 'Aggregation window of the snapshot: weekly, 4‑week, 13‑week, or 52‑week.. Valid values are `monthly|quarterly|weekly`',
  `record_status` STRING COMMENT 'Lifecycle status of the record itself: active, inactive, or archived.. Valid values are `active|inactive|archived`',
  `retailer_banner` STRING COMMENT 'Brand or banner under which the outlet operates (e.g., Walmart, Kroger, Starbucks).',
  `snapshot_date` DATE COMMENT 'Date of the syndicated data snapshot (weekly, 4‑week, etc.).',
  `tdp_change_pct` DECIMAL(18,2) COMMENT 'Percent change in TDP contribution versus prior period.',
  `tdp_contribution_pct` DECIMAL(18,2) COMMENT 'Share of total distribution points contributed by the outlet for the SKU.',
  `updated_timestamp` TIMESTAMP COMMENT 'Timestamp of the most recent update to the distribution point record.',
  `velocity_units_per_point` DECIMAL(18,2) COMMENT 'Average units sold per distribution point for the SKU over the snapshot period.',
  `void_date` DATE COMMENT 'Date on which the SKU distribution was terminated at the outlet.',
  CONSTRAINT pk_distribution_point PRIMARY KEY(`distribution_point_id`),
  CONSTRAINT fk_sales_distribution_point_account_id FOREIGN KEY (`account_id`) REFERENCES `rongzi_catalog_dev`.`sales_core`.`account`(`account_id`) NOT ENFORCED,
  CONSTRAINT fk_sales_distribution_point_brand_id FOREIGN KEY (`brand_id`) REFERENCES `rongzi_catalog_dev`.`marketing_core`.`brand`(`brand_id`) NOT ENFORCED,
  CONSTRAINT fk_sales_distribution_point_sku_id FOREIGN KEY (`sku_id`) REFERENCES `rongzi_catalog_dev`.`master_core`.`sku`(`sku_id`) NOT ENFORCED
)
COMMENT 'SSOT for SKU-level distribution presence, measurement, and periodic syndicated metric snapshots at retail and foodservice locations. Captures store/outlet ID, retailer banner, SKU/GTIN, distribution status (authorized, active, voided), ACV weighted distribution percentage, TDP (Total Distribution Points) contribution, numeric distribution percentage, velocity (units per point of distribution), in-stock status, void date, and periodic snapshot data by time period (weekly, 4-week, 13-week, 52-week) including snapshot date, market area, data source (Nielsen/IRI/Circana), and period-over-period change metrics. Enables distribution health monitoring, new item launch tracking, void management, TDP target attainment reporting, ACV trend analysis, and syndicated data reconciliation. Subsumes all periodic ACV/TDP snapshot reporting previously modeled separately.'
AS SELECT
  TRY_CAST(`distribution_point_id` AS BIGINT) AS `distribution_point_id`,
  TRY_CAST(`account_id` AS BIGINT) AS `account_id`,
  TRY_CAST(`brand_id` AS BIGINT) AS `brand_id`,
  TRY_CAST(`center_id` AS BIGINT) AS `center_id`,
  TRY_CAST(`product_registration_id` AS BIGINT) AS `product_registration_id`,
  TRY_CAST(`sku_id` AS BIGINT) AS `sku_id`,
  TRY_CAST(`acv_change_pct` AS DECIMAL(18,2)) AS `acv_change_pct`,
  TRY_CAST(`acv_weighted_distribution_pct` AS DECIMAL(18,2)) AS `acv_weighted_distribution_pct`,
  nullif(`classification_type`, '') AS `classification_type`,
  TRY_CAST(nullif(`created_timestamp`,'') AS TIMESTAMP) AS `created_timestamp`,
  nullif(`data_source`, '') AS `data_source`,
  nullif(`distribution_point_code`, '') AS `distribution_point_code`,
  nullif(`distribution_status`, '') AS `distribution_status`,
  TRY_CAST(lower(`in_stock_flag`) IN ('true','1','yes') AS BOOLEAN) AS `in_stock_flag`,
  nullif(`location_name`, '') AS `location_name`,
  nullif(`market_area`, '') AS `market_area`,
  TRY_CAST(`numeric_distribution_change_pct` AS DECIMAL(18,2)) AS `numeric_distribution_change_pct`,
  TRY_CAST(`numeric_distribution_pct` AS DECIMAL(18,2)) AS `numeric_distribution_pct`,
  TRY_CAST(`period_over_period_change_pct` AS DECIMAL(18,2)) AS `period_over_period_change_pct`,
  nullif(`period_type`, '') AS `period_type`,
  nullif(`record_status`, '') AS `record_status`,
  nullif(`retailer_banner`, '') AS `retailer_banner`,
  TRY_CAST(nullif(`snapshot_date`,'') AS DATE) AS `snapshot_date`,
  TRY_CAST(`tdp_change_pct` AS DECIMAL(18,2)) AS `tdp_change_pct`,
  TRY_CAST(`tdp_contribution_pct` AS DECIMAL(18,2)) AS `tdp_contribution_pct`,
  TRY_CAST(nullif(`updated_timestamp`,'') AS TIMESTAMP) AS `updated_timestamp`,
  TRY_CAST(`velocity_units_per_point` AS DECIMAL(18,2)) AS `velocity_units_per_point`,
  TRY_CAST(nullif(`void_date`,'') AS DATE) AS `void_date`
FROM `rongzi_catalog_dev`.`ops_landing`.`nielsen__distribution_point_raw`;

-- silver: trade_core.fund  （型変換 + PK/FK + expectations）
CREATE OR REFRESH MATERIALIZED VIEW `rongzi_catalog_dev`.`trade_core`.`fund` (
  `fund_id` BIGINT NOT NULL COMMENT 'System-generated unique identifier for each trade fund record.',
  `brand_id` BIGINT COMMENT 'Foreign key linking to marketing.brand. Business justification: Trade fund allocation is performed per brand; this FK enables fund‑to‑brand reconciliation reports.',
  `employee_id` BIGINT COMMENT 'Internal party (e.g., trade manager) responsible for the fund.',
  `profit_center_id` BIGINT COMMENT 'Foreign key linking to finance.profit_center. Business justification: Trade funds are allocated to specific Profit Centers for performance measurement and internal reporting.',
  `target_id` BIGINT COMMENT 'Foreign key linking to sustainability.sustainability_target. Business justification: Trade fund allocations are tracked against specific ESG targets for the Trade Fund ESG Allocation Report.',
  `accrued_amount` DECIMAL(18,2) COMMENT 'Amount accrued based on spend that has been recognized but not yet paid.',
  `allocation_method` STRING COMMENT 'Method used to distribute the fund across eligible promotions.. Valid values are `proportional|fixed|tiered`',
  `allocation_scope` STRING COMMENT 'Level at which the fund is allocated (e.g., retailer, sales territory, brand/category).. Valid values are `retailer|sales_territory|brand_category`',
  `approval_date` DATE COMMENT 'Date when the fund was approved by finance or trade management.',
  `classification` STRING COMMENT 'High‑level category of the fund purpose (e.g., marketing, price promotion, slotting).. Valid values are `marketing|price_promotion|slotting|display|trade`',
  `committed_amount` DECIMAL(18,2) COMMENT 'Sum of amounts already committed to promotion plans.',
  `created_timestamp` TIMESTAMP COMMENT 'Timestamp when the fund record was first created in the system.',
  `currency_code` STRING COMMENT 'Three‑letter ISO currency code for the fund amounts.. Valid values are `^[A-Z]{3}$`',
  `effective_from` DATE COMMENT 'Date when the fund becomes effective for spend.',
  `effective_until` DATE COMMENT 'Date when the fund expires or is no longer available (nullable for open‑ended).',
  `fiscal_year` STRING COMMENT 'Fiscal year to which the fund belongs.',
  `fund_code` STRING COMMENT 'Business code used to reference the trade fund in external systems and contracts.',
  `fund_description` STRING COMMENT 'Free‑form description providing context or notes about the fund.',
  `fund_name` STRING COMMENT 'Descriptive name of the trade fund for reporting and analysis.',
  `fund_status` STRING COMMENT 'Current lifecycle status of the fund.. Valid values are `active|inactive|closed|pending`',
  `fund_type` STRING COMMENT 'Indicates whether the fund is a lump‑sum, accrual‑based, or fixed allowance allocation.. Valid values are `lump_sum|accrual|fixed_allowance`',
  `paid_amount` DECIMAL(18,2) COMMENT 'Total amount that has been paid out to retailers or partners.',
  `region_code` STRING COMMENT 'Three‑letter code representing the geographic region for the fund allocation.. Valid values are `^[A-Z]{3}$`',
  `remaining_balance` DECIMAL(18,2) COMMENT 'Remaining budget available for future commitments.',
  `source_system` STRING COMMENT 'Name of the source system that supplied the fund data (e.g., SAP S/4HANA, Oracle ERP).',
  `total_approved_amount` DECIMAL(18,2) COMMENT 'Total budget approved for the fund, expressed in the fund currency.',
  `updated_timestamp` TIMESTAMP COMMENT 'Timestamp of the most recent update to the fund record.',
  CONSTRAINT pk_fund PRIMARY KEY(`fund_id`),
  CONSTRAINT fk_trade_fund_profit_center_id FOREIGN KEY (`profit_center_id`) REFERENCES `rongzi_catalog_dev`.`finance_core`.`profit_center`(`profit_center_id`) NOT ENFORCED,
  CONSTRAINT fk_trade_fund_brand_id FOREIGN KEY (`brand_id`) REFERENCES `rongzi_catalog_dev`.`marketing_core`.`brand`(`brand_id`) NOT ENFORCED
)
COMMENT 'Master record for trade spending funds and budgets allocated to retailer accounts, sales territories, or brand/category buckets. Tracks fund type (lump sum, accrual-based, fixed allowance), total approved budget, amount committed to promotion plans, amount accrued, amount paid, and remaining balance. Supports trade spend governance and budget control. Sourced from SAP S/4HANA CO and TPM fund management modules.'
AS SELECT
  TRY_CAST(`fund_id` AS BIGINT) AS `fund_id`,
  TRY_CAST(`brand_id` AS BIGINT) AS `brand_id`,
  TRY_CAST(`employee_id` AS BIGINT) AS `employee_id`,
  TRY_CAST(`profit_center_id` AS BIGINT) AS `profit_center_id`,
  TRY_CAST(`target_id` AS BIGINT) AS `target_id`,
  TRY_CAST(`accrued_amount` AS DECIMAL(18,2)) AS `accrued_amount`,
  nullif(`allocation_method`, '') AS `allocation_method`,
  nullif(`allocation_scope`, '') AS `allocation_scope`,
  TRY_CAST(nullif(`approval_date`,'') AS DATE) AS `approval_date`,
  nullif(`classification`, '') AS `classification`,
  TRY_CAST(`committed_amount` AS DECIMAL(18,2)) AS `committed_amount`,
  TRY_CAST(nullif(`created_timestamp`,'') AS TIMESTAMP) AS `created_timestamp`,
  nullif(`currency_code`, '') AS `currency_code`,
  TRY_CAST(nullif(`effective_from`,'') AS DATE) AS `effective_from`,
  TRY_CAST(nullif(`effective_until`,'') AS DATE) AS `effective_until`,
  nullif(`fiscal_year`, '') AS `fiscal_year`,
  nullif(`fund_code`, '') AS `fund_code`,
  nullif(`fund_description`, '') AS `fund_description`,
  nullif(`fund_name`, '') AS `fund_name`,
  nullif(`fund_status`, '') AS `fund_status`,
  nullif(`fund_type`, '') AS `fund_type`,
  TRY_CAST(`paid_amount` AS DECIMAL(18,2)) AS `paid_amount`,
  nullif(`region_code`, '') AS `region_code`,
  TRY_CAST(`remaining_balance` AS DECIMAL(18,2)) AS `remaining_balance`,
  nullif(`source_system`, '') AS `source_system`,
  TRY_CAST(`total_approved_amount` AS DECIMAL(18,2)) AS `total_approved_amount`,
  TRY_CAST(nullif(`updated_timestamp`,'') AS TIMESTAMP) AS `updated_timestamp`
FROM `rongzi_catalog_dev`.`ops_landing`.`tpm__fund_raw`;

-- silver: trade_core.promotion_event  （型変換 + PK/FK + expectations）
CREATE OR REFRESH MATERIALIZED VIEW `rongzi_catalog_dev`.`trade_core`.`promotion_event` (
  `promotion_event_id` BIGINT NOT NULL COMMENT 'Unique identifier for the promotion event record.',
  `campaign_id` BIGINT COMMENT 'Foreign key linking to marketing.campaign. Business justification: Required for Campaign‑Promotion ROI report linking each promotion event to its originating marketing campaign.',
  `cost_center_id` BIGINT COMMENT 'Foreign key linking to finance.cost_center. Business justification: Promotion expense must be posted to a Cost Center for budgeting and P&L reporting; finance cost_center tracks these allocations.',
  `employee_id` BIGINT COMMENT 'User identifier who created the promotion event record.',
  `price_list_id` BIGINT COMMENT 'Foreign key linking to pricing.price_list. Business justification: Promotion events generate price list updates; linking event to the price list allows the Promotion Execution Dashboard to associate price changes with the originating event.',
  `promotion_plan_id` BIGINT COMMENT 'Identifier of the parent promotion plan.',
  `rd_project_id` BIGINT COMMENT 'Foreign key linking to research.rd_project. Business justification: Promotion events execute the launch of a product defined by an R&D project; linking tracks spend per project.',
  `account_id` BIGINT COMMENT 'Identifier of the retailer account where the promotion was executed.',
  `store_cluster_id` BIGINT COMMENT 'Identifier of the store cluster (geographic grouping) for the promotion execution.',
  `actual_end_date` DATE COMMENT 'Actual end date when the promotion concluded at the retailer.',
  `actual_revenue` DECIMAL(18,2) COMMENT 'Actual revenue generated by the promotion.',
  `actual_sales_volume` STRING COMMENT 'Actual sales volume achieved during the promotion.',
  `actual_start_date` DATE COMMENT 'Actual start date when the promotion began at the retailer.',
  `approval_timestamp` TIMESTAMP COMMENT 'Timestamp when the promotion event record was approved by audit.',
  `audit_status` STRING COMMENT 'Internal audit status of the promotion event record.. Valid values are `pending|approved|rejected`',
  `channel` STRING COMMENT 'Sales channel(s) where the promotion was applied.. Valid values are `CVS|DgS|EC|SM|卸`',
  `compliance_notes` STRING COMMENT 'Free-text notes regarding compliance observations.',
  `compliance_status` STRING COMMENT 'Compliance assessment result for the promotion execution.. Valid values are `compliant|non_compliant|partial|pending_review`',
  `created_timestamp` TIMESTAMP COMMENT 'Timestamp when the promotion event record was created in the system.',
  `currency_code` STRING COMMENT 'ISO 4217 currency code for monetary amounts.. Valid values are `USD|CAD|EUR|GBP|JPY|AUD`',
  `event_number` STRING COMMENT 'Business reference number for the promotion event.',
  `execution_timestamp` TIMESTAMP COMMENT 'Timestamp when the promotion event was actually executed in the field.',
  `field_verification_timestamp` TIMESTAMP COMMENT 'Timestamp of the field verification.',
  `is_field_verified` BOOLEAN COMMENT 'Indicates whether field execution was verified by a supervisor.',
  `last_modified_by` STRING COMMENT 'User identifier who last modified the promotion event record.',
  `mechanic_type` STRING COMMENT 'Type of promotional mechanic deployed for the event.. Valid values are `BOGO|TPR|増量|多数買い`',
  `notes` STRING COMMENT 'Additional free-text notes about the promotion event.',
  `planned_end_date` DATE COMMENT 'Planned end date of the promotion as per the promotion plan.',
  `planned_start_date` DATE COMMENT 'Planned start date of the promotion as per the promotion plan.',
  `product_category` STRING COMMENT 'High-level product category targeted by the promotion.',
  `promotion_event_status` STRING COMMENT 'Current lifecycle status of the promotion event.. Valid values are `closed|executing|planned`',
  `promotion_objective` STRING COMMENT 'Primary business objective of the promotion.. Valid values are `distribution|share|trial|volume`',
  `promotion_type` STRING COMMENT 'Category of promotion type applied.. Valid values are `bonus_pack|coupon|end_aisle|feature_display|price_discount`',
  `promotional_materials_delivered` BOOLEAN COMMENT 'Flag indicating if promotional materials were delivered to the store.',
  `promotional_materials_quantity` STRING COMMENT 'Quantity of promotional materials delivered.',
  `promotional_materials_type` STRING COMMENT 'Type of promotional materials used for the event.. Valid values are `display|shelf_tag|flyer|digital|sample`',
  `promotional_spend_discount` DECIMAL(18,2) COMMENT 'Total discount or chargeback amount applied to the promotional spend.',
  `promotional_spend_gross` DECIMAL(18,2) COMMENT 'Gross promotional spend amount before any deductions.',
  `promotional_spend_net` DECIMAL(18,2) COMMENT 'Net promotional spend after discounts and chargebacks.',
  `region_code` STRING COMMENT 'Three-letter region code (e.g., USA, CAN) for the promotion execution.. Valid values are `^[A-Z]{3}$`',
  `sku_list` STRING COMMENT 'Comma-separated list of SKUs included in the promotion.',
  `store_count_actual` STRING COMMENT 'Number of stores that actually executed the promotion.',
  `store_count_planned` STRING COMMENT 'Number of stores originally scheduled to participate in the promotion.',
  `target_revenue` DECIMAL(18,2) COMMENT 'Planned revenue target for the promotion.',
  `target_sales_volume` STRING COMMENT 'Planned sales volume target (units) for the promotion.',
  `updated_timestamp` TIMESTAMP COMMENT 'Timestamp of the most recent update to the promotion event record.',
  CONSTRAINT pk_promotion_event PRIMARY KEY(`promotion_event_id`),
  CONSTRAINT fk_trade_promotion_event_account_id FOREIGN KEY (`account_id`) REFERENCES `rongzi_catalog_dev`.`sales_core`.`account`(`account_id`) NOT ENFORCED,
  CONSTRAINT fk_trade_promotion_event_cost_center_id FOREIGN KEY (`cost_center_id`) REFERENCES `rongzi_catalog_dev`.`finance_core`.`cost_center`(`cost_center_id`) NOT ENFORCED,
  CONSTRAINT fk_trade_promotion_event_campaign_id FOREIGN KEY (`campaign_id`) REFERENCES `rongzi_catalog_dev`.`marketing_core`.`campaign`(`campaign_id`) NOT ENFORCED
)
COMMENT 'Transactional record capturing the execution of a trade promotion event at a specific retailer account and store cluster. Tracks actual execution dates, participating store count, promotional mechanic deployed (e.g., end-cap display, circular feature, TPR shelf tag), compliance status, and field execution confirmation. Links to the parent promotion plan and captures variance between planned and actual execution. Sourced from Salesforce CRM Sales Cloud and field execution data.'
AS SELECT
  TRY_CAST(`promotion_event_id` AS BIGINT) AS `promotion_event_id`,
  TRY_CAST(`campaign_id` AS BIGINT) AS `campaign_id`,
  TRY_CAST(`cost_center_id` AS BIGINT) AS `cost_center_id`,
